        .target = target,
        .optimize = optimize,
    });

    const pattern_parser_tests = b.addTest(.{
        .root_source_file = b.path("test/phase3_pattern_parser_test.zig"),
        .target = target,
        .optimize = optimize,
    });

    const pattern_astgen_tests = b.addTest(.{
        .root_source_file = b.path("test/phase3_pattern_astgen_test.zig"),
        .target = target,
        .optimize = optimize,
