     1→// 🦎 Mini Zig Compiler - Phase 2.4: AIR
     2→// src/air.zig: Analyzed Intermediate Representation (with Type Information)
     3→
     4→const std = @import("std");
     5→
     6→/// Type System
     7→pub const Type = union(enum) {
     8→    void,
     9→    i32,
    10→    i64,
    11→    f32,
    12→    f64,
    13→    bool,
    14→    string,
    15→    array: struct {
    16→        element_ty: *Type,
    17→        len: ?usize,
    18→    },
    19→    slice: struct {
    20→        element_ty: *Type,
    21→        is_const: bool = false,
    22→    },
    23→    function: struct {
    24→        params: []Type,
    25→        return_ty: *Type,
    26→    },
    27→    // Phase 3.7: Error Handling
    28→    error_type: struct {
    29→        name: []const u8,
    30→        variants: [][]const u8,  // NotFound, IO, ... 에러 이름들
    31→    },
    32→    error_union: struct {
    33→        base_type: *Type,
    34→        error_type: *Type,
    35→    },
    36→    // Phase 3.8: Pattern Matching
    37→    pattern: struct {
    38→        pattern_type: PatternType,
    39→        variants: []PatternVariant,  // 패턴 케이스들
    40→    },
    41→    unknown, // 아직 추론되지 않음
    42→};
    43→
    44→/// AIR Instruction (with Type Information)
    45→pub const Instruction = union(enum) {
    46→    // 리터럴 (타입 정보 포함)
    47→    load_int: struct { value: i64, ty: Type },
    48→    load_float: struct { value: f64, ty: Type },
    49→    load_string: struct { index: u32, ty: Type },
    50→
    51→    // 변수 (타입 정보 포함)
    52→    load_var: struct { name_index: u32, ty: Type },
    53→    store_var: struct { name_index: u32, value: Ref, ty: Type },
    54→
    55→    // 연산자 (연산 결과 타입 포함)
    56→    binary_op: struct { op: BinaryOp, lhs: Ref, rhs: Ref, result_ty: Type },
    57→    unary_op: struct { op: UnaryOp, operand: Ref, result_ty: Type },
    58→
    59→    // 함수
    60→    fn_begin: struct { name_index: u32, params: []Ref, return_ty: Type },
    61→    fn_end,
    62→
    63→    // 제어 흐름
    64→    call: struct { callee: Ref, args: []Ref, return_ty: Type },
    65→    br: Ref,
    66→    cond_br: struct { cond: Ref, then_block: Ref, else_block: ?Ref },
    67→    return_val: ?Ref,
    68→
    69→    // 블록
    70→    block_begin: struct { label: u32 },
    71→    block_end,
    72→
    73→    // 배열/메모리
    74→    array_literal: struct { elements: []Ref, element_ty: Type },
    75→    index_access: struct { array: Ref, index: Ref, element_ty: Type },
    76→    member_access: struct { object: Ref, field_index: u32, field_ty: Type },
    77→
    78→    // 제어 흐름 (advanced)
    79→    loop_begin: struct { label: u32 },
    80→    loop_end,
    81→    break_loop: struct { label: u32 },
    82→    continue_loop: struct { label: u32 },
    83→
    84→    // Phase 3.6: Defer & Resource Management
    85→    defer_stmt: struct {
    86→        expr: Ref,
    87→        scope_id: u32,
    88→        defer_index: u32,
    89→    },
    90→
    91→    scope_exit: struct {
    92→        scope_id: u32,
    93→        deferred_count: u32,  // 이 스코프의 defer 실행 개수
    94→    },
    95→
    96→    // Phase 3.7: Error Handling
    97→    try_expr: struct {
    98→        expr: Ref,
    99→        result_type: Type,  // try 식의 결과 타입
   100→    },
   101→
   102→    catch_expr: struct {
   103→        try_expr: Ref,
   104→        error_var_type: Type,  // catch |err|에서 err의 타입
   105→        body: Ref,
   106→    },
   107→
   108→    // Phase 3.8: Pattern Matching
   109→    switch_expr: struct {
   110→        expr: Ref,
   111→        cases: []Ref,  // 각 케이스 value 들
   112→        case_patterns: []Type,  // 각 패턴의 타입
   113→    },
   114→
   115→    case_pattern: struct {
   116→        pattern: Ref,
   117→        value: Ref,
   118→        pattern_ty: Type,
   119→    },
   120→
   121→    // 기타
   122→    noop,
   123→};
   124→
   125→pub const Ref = u32; // Instruction 인덱스
   126→
   127→pub const BinaryOp = enum {
   128→    add, sub, mul, div, mod,
   129→    eq, ne, lt, le, gt, ge,
   130→    logical_and, logical_or,
   131→    bitwise_and, bitwise_or, bitwise_xor,
   132→    lshift, rshift,
   133→};
   134→
   135→pub const UnaryOp = enum {
   136→    negate, not, bitwise_not,
   137→};
   138→
   139→// Phase 3.8: Pattern Matching
   140→pub const PatternType = enum {
   141→    literal,
   142→    tuple,
   143→    struct,
   144→    type_pat,
   145→    union_variant,
   146→    wildcard,
   147→    variable,
   148→};
   149→
   150→pub const PatternVariant = struct {
   151→    name: []const u8,
   152→    field_types: []Type,
   153→};
   154→
   155→/// AIR - Analyzed Intermediate Representation
   156→pub const Air = struct {
   157→    instructions: std.ArrayList(Instruction),
   158→    extra: std.ArrayList(u32),
   159→    strings: std.StringHashMap([]const u8),
   160→    allocator: std.mem.Allocator,
   161→
   162→    pub fn init(allocator: std.mem.Allocator) Air {
   163→        return .{
   164→            .instructions = std.ArrayList(Instruction).init(allocator),
   165→            .extra = std.ArrayList(u32).init(allocator),
   166→            .strings = std.StringHashMap([]const u8).init(allocator),
   167→            .allocator = allocator,
   168→        };
   169→    }
   170→
   171→    pub fn deinit(self: *Air) void {
   172→        self.instructions.deinit();
   173→        self.extra.deinit();
   174→        self.strings.deinit();
   175→    }
   176→
   177→    /// 명령어 추가 및 Ref 반환
   178→    pub fn addInstruction(self: *Air, inst: Instruction) !Ref {
   179→        const index: Ref = @intCast(self.instructions.items.len);
   180→        try self.instructions.append(inst);
   181→        return index;
   182→    }
   183→
   184→    /// 문자열 추가 및 인덱스 반환
   185→    pub fn addString(self: *Air, text: []const u8) !u32 {
   186→        if (self.strings.get(text)) |_| {
   187→            return @intCast(self.strings.count() - 1);
   188→        }
   189→
   190→        const index: u32 = @intCast(self.strings.count());
   191→        try self.strings.put(text, text);
   192→        return index;
   193→    }
   194→
   195→    /// 추가 데이터 저장소에 값 추가
   196→    pub fn addExtra(self: *Air, value: u32) !u32 {
   197→        const index: u32 = @intCast(self.extra.items.len);
   198→        try self.extra.append(value);
   199→        return index;
   200→    }
   201→};
   202→
   203→/// Type 유틸리티 함수들
   204→pub fn typeEq(t1: Type, t2: Type) bool {
   205→    switch (t1) {
   206→        .void => return t2 == .void,
   207→        .i32 => return t2 == .i32,
   208→        .i64 => return t2 == .i64,
   209→        .f32 => return t2 == .f32,
   210→        .f64 => return t2 == .f64,
   211→        .bool => return t2 == .bool,
   212→        .string => return t2 == .string,
   213→        .unknown => return t2 == .unknown,
   214→        .array => |arr1| {
   215→            if (t2 == .array) {
   216→                const arr2 = t2.array;
   217→                return typeEq(arr1.element_ty.*, arr2.element_ty.*) and
   218→                    arr1.len == arr2.len;
   219→            }
   220→            return false;
   221→        },
   222→        .function => {
   223→            // 함수 타입 비교는 복잡하므로 나중에 구현
   224→            return false;
   225→        },
   226→    }
   227→}
   228→
   229→pub fn typeName(t: Type) []const u8 {
   230→    return switch (t) {
   231→        .void => "void",
   232→        .i32 => "i32",
   233→        .i64 => "i64",
   234→        .f32 => "f32",
   235→        .f64 => "f64",
   236→        .bool => "bool",
   237→        .string => "string",
   238→        .unknown => "unknown",
   239→        .array => "array",
   240→        .function => "function",
   241→    };
   242→}
   243→
   244→/// AIR 디버깅용 출력 함수
   245→pub fn printAir(air: *const Air, indent: usize) void {
   246→    const spaces = " " ** indent;
   247→    const stdout = std.io.getStdOut().writer();
   248→
   249→    stdout.print("{s}=== AIR Instructions ===\n", .{spaces}) catch {};
   250→
   251→    for (air.instructions.items, 0..) |inst, idx| {
   252→        stdout.print("{s}[{}] ", .{ spaces, idx }) catch {};
   253→
   254→        switch (inst) {
   255→            .load_int => |data| {
   256→                stdout.print("load_int {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   257→            },
   258→            .load_float => |data| {
   259→                stdout.print("load_float {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   260→            },
   261→            .load_string => |data| {
   262→                stdout.print("load_string @{} ({s})\n", .{ data.index, typeName(data.ty) }) catch {};
   263→            },
   264→            .load_var => |data| {
   265→                stdout.print("load_var @{} ({s})\n", .{ data.name_index, typeName(data.ty) }) catch {};
   266→            },
   267→            .store_var => |data| {
   268→                stdout.print("store_var @{} = %{} ({s})\n", .{ data.name_index, data.value, typeName(data.ty) }) catch {};
   269→            },
   270→            .binary_op => |data| {
   271→                stdout.print("binary_op {:s} %{} %{} → {s}\n", .{ @tagName(data.op), data.lhs, data.rhs, typeName(data.result_ty) }) catch {};
   272→            },
   273→            .unary_op => |data| {
   274→                stdout.print("unary_op {:s} %{} → {s}\n", .{ @tagName(data.op), data.operand, typeName(data.result_ty) }) catch {};
   275→            },
   276→            .fn_begin => |data| {
   277→                stdout.print("fn_begin @{} (params: {}, return: {s})\n", .{ data.name_index, data.params.len, typeName(data.return_ty) }) catch {};
   278→            },
   279→            .fn_end => {
