     1→const std = @import("std");
     2→const Air = @import("air.zig").Air;
     3→const AirType = @import("air.zig").Type;
     4→const Ref = @import("air.zig").Ref;
     5→const Instruction = @import("air.zig").Instruction;
     6→
     7→/// C 코드 생성기 (AIR → C 코드)
     8→pub const Codegen = struct {
     9→    air: *const Air,
    10→    allocator: std.mem.Allocator,
    11→    output: std.ArrayList(u8),
    12→    indent_level: usize,
    13→    temp_counter: u32,
    14→    ref_to_temp: std.AutoHashMap(Ref, []const u8),
    15→
    16→    pub fn init(allocator: std.mem.Allocator, air: *const Air) !Codegen {
    17→        return Codegen{
    18→            .air = air,
    19→            .allocator = allocator,
    20→            .output = std.ArrayList(u8).init(allocator),
    21→            .indent_level = 0,
    22→            .temp_counter = 0,
    23→            .ref_to_temp = std.AutoHashMap(Ref, []const u8).init(allocator),
    24→        };
    25→    }
    26→
    27→    pub fn deinit(self: *Codegen) void {
    28→        self.output.deinit();
    29→        self.ref_to_temp.deinit();
    30→    }
    31→
    32→    /// AIR 프로그램을 C 코드로 생성
    33→    pub fn generate(self: *Codegen) ![]const u8 {
    34→        try self.emitHeaders();
    35→        try self.emitDeclarations();
    36→        return self.output.items;
    37→    }
    38→
    39→    /// 생성된 C 코드를 파일로 저장
    40→    pub fn generateToFile(self: *Codegen, path: []const u8) !void {
    41→        const c_code = try self.generate();
    42→        const file = try std.fs.cwd().createFile(path, .{});
    43→        defer file.close();
    44→        try file.writeAll(c_code);
    45→    }
    46→
    47→    // ========== 헤더 & 기본 구조 ==========
    48→
    49→    fn emitHeaders(self: *Codegen) !void {
    50→        try self.output.appendSlice("#include <stdio.h>\n");
    51→        try self.output.appendSlice("#include <string.h>\n");
    52→        try self.output.appendSlice("#include <stdlib.h>\n\n");
    53→    }
    54→
    55→    fn emitDeclarations(self: *Codegen) !void {
    56→        for (self.air.instructions.items, 0..) |inst, idx| {
    57→            const ref: Ref = @intCast(idx);
    58→            try self.emitInstruction(inst, ref);
    59→        }
    60→    }
    61→
    62→    // ========== 타입 변환 ==========
    63→
    64→    fn typeToCString(self: *Codegen, ty: AirType) ![]const u8 {
    65→        _ = self;
    66→        return switch (ty) {
    67→            .void => "void",
    68→            .i32 => "int",
    69→            .i64 => "long long",
    70→            .f32 => "float",
    71→            .f64 => "double",
    72→            .bool => "int",
    73→            .string => "const char*",
    74→            .array => "array", // TODO: 배열 타입 처리
    75→            .function => "function", // TODO: 함수 포인터
    76→            .unknown => "int", // 기본값
    77→        };
    78→    }
    79→
    80→    /// Ref를 C 코드 표현으로 변환 (변수명 또는 리터럴)
    81→    fn refToString(self: *Codegen, ref: Ref) ![]const u8 {
    82→        if (self.ref_to_temp.get(ref)) |temp| {
    83→            return temp;
    84→        }
    85→        return try std.fmt.allocPrint(self.allocator, "_t{}", .{ref});
    86→    }
    87→
    88→    /// 새로운 임시 변수 생성
    89→    fn genTempVar(self: *Codegen) ![]const u8 {
    90→        const name = try std.fmt.allocPrint(self.allocator, "_t{}", .{self.temp_counter});
    91→        self.temp_counter += 1;
    92→        return name;
    93→    }
    94→
    95→    // ========== Instruction 코드 생성 ==========
    96→
    97→    fn emitInstruction(self: *Codegen, inst: Instruction, ref: Ref) !void {
    98→        switch (inst) {
    99→            .load_int => |info| {
   100→                try self.emitLoadInt(info, ref);
   101→            },
   102→            .load_float => |info| {
   103→                try self.emitLoadFloat(info, ref);
   104→            },
   105→            .load_string => |info| {
   106→                try self.emitLoadString(info, ref);
   107→            },
   108→            .load_var => |info| {
   109→                try self.emitLoadVar(info, ref);
   110→            },
   111→            .store_var => |info| {
   112→                try self.emitStoreVar(info);
   113→            },
   114→            .binary_op => |info| {
   115→                try self.emitBinaryOp(info, ref);
   116→            },
   117→            .unary_op => |info| {
   118→                try self.emitUnaryOp(info, ref);
   119→            },
   120→            .fn_begin => |info| {
   121→                try self.emitFnBegin(info);
   122→            },
   123→            .fn_end => {
   124→                try self.emitFnEnd();
   125→            },
   126→            .call => |info| {
   127→                try self.emitCall(info, ref);
   128→            },
   129→            .cond_br => |info| {
   130→                try self.emitCondBr(info);
   131→            },
   132→            .return_val => |info| {
   133→                try self.emitReturnVal(info);
   134→            },
   135→            .block_begin => {
   136→                try self.emitIndent();
   137→                try self.output.appendSlice("{\n");
   138→                self.indent_level += 1;
   139→            },
   140→            .block_end => {
   141→                if (self.indent_level > 0) self.indent_level -= 1;
   142→                try self.emitIndent();
   143→                try self.output.appendSlice("}\n");
   144→            },
   145→            .array_literal => |info| {
   146→                try self.emitArrayLiteral(info, ref);
   147→            },
   148→            .index_access => |info| {
   149→                try self.emitIndexAccess(info, ref);
   150→            },
   151→            .member_access => |info| {
   152→                try self.emitMemberAccess(info, ref);
   153→            },
   154→            .loop_begin => {
   155→                try self.emitIndent();
   156→                try self.output.appendSlice("while (1) {\n");
   157→                self.indent_level += 1;
   158→            },
   159→            .loop_end => {
   160→                if (self.indent_level > 0) self.indent_level -= 1;
   161→                try self.emitIndent();
   162→                try self.output.appendSlice("}\n");
   163→            },
   164→            .noop => {},
   165→            else => {},
   166→        }
   167→    }
   168→
   169→    fn emitLoadInt(self: *Codegen, info: struct { value: i64, ty: AirType }, ref: Ref) !void {
   170→        try self.emitIndent();
   171→        const type_str = try self.typeToCString(info.ty);
   172→        try self.output.appendSlice(type_str);
   173→        try self.output.appendSlice(" _t");
   174→        try self.output.writer().print("{} = {};\n", .{ ref, info.value });
   175→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   176→    }
   177→
   178→    fn emitLoadFloat(self: *Codegen, info: struct { value: f64, ty: AirType }, ref: Ref) !void {
   179→        try self.emitIndent();
   180→        const type_str = try self.typeToCString(info.ty);
   181→        try self.output.appendSlice(type_str);
   182→        try self.output.appendSlice(" _t");
   183→        try self.output.writer().print("{} = {};\n", .{ ref, info.value });
   184→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   185→    }
   186→
   187→    fn emitLoadString(self: *Codegen, info: struct { index: u32, ty: AirType }, ref: Ref) !void {
   188→        try self.emitIndent();
   189→        const type_str = try self.typeToCString(info.ty);
   190→        const str_value = if (info.index < self.air.strings.items.len)
   191→            self.air.strings.items[info.index]
   192→        else
   193→            "\"\"";
   194→        try self.output.writer().print("{} _t{} = {};\n", .{ type_str, ref, str_value });
   195→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   196→    }
   197→
   198→    fn emitLoadVar(self: *Codegen, info: struct { name_index: u32, ty: AirType }, ref: Ref) !void {
   199→        try self.emitIndent();
   200→        const type_str = try self.typeToCString(info.ty);
   201→        const var_name = if (info.name_index < self.air.strings.items.len)
   202→            self.air.strings.items[info.name_index]
   203→        else
   204→            "unknown";
   205→        try self.output.writer().print("{} _t{} = {};\n", .{ type_str, ref, var_name });
   206→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   207→    }
   208→
   209→    fn emitStoreVar(self: *Codegen, info: struct { name_index: u32, value: Ref, ty: AirType }) !void {
   210→        try self.emitIndent();
   211→        const var_name = if (info.name_index < self.air.strings.items.len)
   212→            self.air.strings.items[info.name_index]
   213→        else
   214→            "unknown";
   215→        const val_str = try self.refToString(info.value);
   216→        try self.output.writer().print("{} = {};\n", .{ var_name, val_str });
   217→    }
   218→
   219→    fn emitBinaryOp(self: *Codegen, info: struct { op: u8, lhs: Ref, rhs: Ref, result_ty: AirType }, ref: Ref) !void {
   220→        try self.emitIndent();
   221→        const type_str = try self.typeToCString(info.result_ty);
   222→        const op_str = switch (info.op) {
   223→            0 => "+",    // add
   224→            1 => "-",    // sub
   225→            2 => "*",    // mul
   226→            3 => "/",    // div
   227→            4 => "%",    // mod
   228→            5 => "==",   // eq
   229→            6 => "!=",   // ne
   230→            7 => "<",    // lt
   231→            8 => "<=",   // le
   232→            9 => ">",    // gt
   233→            10 => ">=",  // ge
   234→            11 => "&&",  // and
   235→            12 => "||",  // or
   236→            13 => "^",   // xor
   237→            14 => "<<",  // lshift
   238→            15 => ">>",  // rshift
   239→            else => "+",
   240→        };
   241→        const lhs_str = try self.refToString(info.lhs);
   242→        const rhs_str = try self.refToString(info.rhs);
   243→        try self.output.writer().print("{} _t{} = {} {} {};\n", .{ type_str, ref, lhs_str, op_str, rhs_str });
   244→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   245→    }
   246→
   247→    fn emitUnaryOp(self: *Codegen, info: struct { op: u8, operand: Ref, result_ty: AirType }, ref: Ref) !void {
   248→        try self.emitIndent();
   249→        const type_str = try self.typeToCString(info.result_ty);
   250→        const op_str = switch (info.op) {
   251→            0 => "-",  // negate
   252→            1 => "!",  // not
   253→            2 => "~",  // bitwise_not
   254→            else => "-",
   255→        };
   256→        const operand_str = try self.refToString(info.operand);
   257→        try self.output.writer().print("{} _t{} = {}{};\n", .{ type_str, ref, op_str, operand_str });
   258→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   259→    }
   260→
   261→    fn emitFnBegin(self: *Codegen, info: struct { name_index: u32, params: []Ref, return_ty: AirType }) !void {
   262→        try self.emitIndent();
   263→        const fn_name = if (info.name_index < self.air.strings.items.len)
   264→            self.air.strings.items[info.name_index]
   265→        else
   266→            "unknown";
   267→        const return_str = try self.typeToCString(info.return_ty);
   268→        try self.output.writer().print("{} {}(", .{ return_str, fn_name });
   269→
   270→        // 파라미터 출력 (간단하게 int로 표현)
   271→        for (0..info.params.len) |i| {
   272→            if (i > 0) try self.output.appendSlice(", ");
   273→            try self.output.writer().print("int p{}", .{i});
   274→        }
   275→        try self.output.appendSlice(") {\n");
   276→        self.indent_level += 1;
   277→    }
   278→
   279→    fn emitFnEnd(self: *Codegen) !void {
   280→        if (self.indent_level > 0) self.indent_level -= 1;
   281→        try self.emitIndent();
   282→        try self.output.appendSlice("}\n\n");
   283→    }
   284→
   285→    fn emitCall(self: *Codegen, info: struct { callee: Ref, args: []Ref, return_ty: AirType }, ref: Ref) !void {
   286→        try self.emitIndent();
   287→        const type_str = try self.typeToCString(info.return_ty);
   288→        const callee_str = try self.refToString(info.callee);
   289→        try self.output.writer().print("{} _t{} = {}(", .{ type_str, ref, callee_str });
   290→
   291→        for (0..info.args.len) |i| {
   292→            if (i > 0) try self.output.appendSlice(", ");
   293→            const arg_str = try self.refToString(info.args[i]);
   294→            try self.output.appendSlice(arg_str);
   295→        }
   296→        try self.output.appendSlice(");\n");
   297→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   298→    }
   299→
   300→    fn emitCondBr(self: *Codegen, info: struct { cond: Ref, then_block: Ref, else_block: ?Ref }) !void {
   301→        try self.emitIndent();
   302→        const cond_str = try self.refToString(info.cond);
   303→        _ = info.else_block; // 단순 if 처리, else는 별도 블록
   304→        try self.output.writer().print("if ({}) ", .{cond_str});
   305→    }
   306→
   307→    fn emitReturnVal(self: *Codegen, value: ?Ref) !void {
   308→        try self.emitIndent();
   309→        try self.output.appendSlice("return");
   310→        if (value) |v| {
   311→            try self.output.appendSlice(" ");
   312→            const val_str = try self.refToString(v);
   313→            try self.output.appendSlice(val_str);
   314→        }
   315→        try self.output.appendSlice(";\n");
   316→    }
   317→
   318→    fn emitArrayLiteral(self: *Codegen, info: struct { elements: []Ref, element_ty: AirType }, ref: Ref) !void {
   319→        try self.emitIndent();
   320→        const type_str = try self.typeToCString(info.element_ty);
   321→        try self.output.writer().print("{} _t{}[] = {{ ", .{ type_str, ref });
   322→        for (0..info.elements.len) |i| {
   323→            if (i > 0) try self.output.appendSlice(", ");
   324→            const elem_str = try self.refToString(info.elements[i]);
   325→            try self.output.appendSlice(elem_str);
   326→        }
   327→        try self.output.appendSlice(" };\n");
   328→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   329→    }
   330→
   331→    fn emitIndexAccess(self: *Codegen, info: struct { array: Ref, index: Ref, element_ty: AirType }, ref: Ref) !void {
   332→        try self.emitIndent();
   333→        const type_str = try self.typeToCString(info.element_ty);
   334→        const array_str = try self.refToString(info.array);
   335→        const index_str = try self.refToString(info.index);
   336→        try self.output.writer().print("{} _t{} = {}[{}];\n", .{ type_str, ref, array_str, index_str });
   337→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   338→    }
   339→
   340→    fn emitMemberAccess(self: *Codegen, info: struct { object: Ref, field_index: u32, field_ty: AirType }, ref: Ref) !void {
   341→        try self.emitIndent();
   342→        const type_str = try self.typeToCString(info.field_ty);
   343→        const object_str = try self.refToString(info.object);
   344→        const field_name = if (info.field_index < self.air.strings.items.len)
   345→            self.air.strings.items[info.field_index]
   346→        else
   347→            "field";
   348→        try self.output.writer().print("{} _t{} = {}.{};\n", .{ type_str, ref, object_str, field_name });
   349→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   350→    }
   351→
   352→    // ========== 유틸리티 ==========
   353→
   354→    fn emitIndent(self: *Codegen) !void {
   355→        for (0..self.indent_level) |_| {
   356→            try self.output.appendSlice("    ");
   357→        }
   358→    }
   359→};
