     1→const std = @import("std");
     2→const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
     3→const Parser = @import("../src/parser.zig").Parser;
     4→const AstGen = @import("../src/astgen.zig").AstGen;
     5→const Sema = @import("../src/sema.zig").Sema;
     6→const Codegen = @import("../src/codegen.zig").Codegen;
     7→
     8→/// 소스 코드를 C 코드로 컴파일하는 헬퍼 함수
     9→fn compileToC(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    10→    var tokenizer = try Tokenizer.init(source, allocator);
    11→    defer tokenizer.deinit();
    12→
    13→    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    14→    defer tokens.deinit();
    15→
    16→    while (try tokenizer.nextToken()) |token| {
    17→        try tokens.append(token);
    18→    }
    19→
    20→    var parser = try Parser.init(tokens.items, source, allocator);
    21→    defer parser.deinit();
    22→    const ast = try parser.parseProgram();
    23→
    24→    var astgen = try AstGen.init(allocator, source);
    25→    defer astgen.deinit();
    26→    try astgen.genProgram(&ast);
    27→
    28→    var sema = try Sema.init(allocator, &astgen.zir);
    29→    defer sema.deinit();
    30→    try sema.analyzeProgram();
    31→
    32→    var codegen = try Codegen.init(allocator, &sema.air);
    33→    defer codegen.deinit();
    34→    const c_code = try codegen.generate();
    35→
    36→    return c_code;
    37→}
