     4→const std = @import("std");
     5→const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
     6→const Parser = @import("../src/parser.zig").Parser;
     7→const Ast = @import("../src/ast.zig");
     8→const AstGen = @import("../src/astgen.zig").AstGen;
     9→const Sema = @import("../src/sema.zig").Sema;
    10→
    11→fn createSema(allocator: std.mem.Allocator, source: []const u8) !Sema {
    12→    var tokenizer = Tokenizer.init(source);
    13→    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    14→    defer tokens.deinit();
    15→
    16→    while (true) {
    17→        const token = tokenizer.nextToken();
    18→        try tokens.append(token);
    19→        if (token.tag == .eof) break;
    20→    }
    21→
    22→    var parser = try Parser.init(try tokens.toOwnedSlice(), source, allocator);
    23→    const ast = try parser.parseProgram();
    24→    defer ast.deinit();
    25→
    26→    var astgen = try AstGen.init(allocator, source);
    27→    try astgen.genProgram(&ast);
    28→    defer astgen.deinit();
    29→
    30→    return try Sema.init(allocator, astgen.zir);
    31→}
