     4→const std = @import("std");
     5→const Tokenizer = @import("../src/tokenizer.zig").Tokenizer;
     6→const Parser = @import("../src/parser.zig").Parser;
     7→const AstGen = @import("../src/astgen.zig").AstGen;
     8→const Sema = @import("../src/sema.zig").Sema;
     9→const Air = @import("../src/air.zig").Air;
    10→const AirType = @import("../src/air.zig").Type;
    11→const Ast = @import("../src/ast.zig");
    12→
    13→fn createSema(allocator: std.mem.Allocator, source: []const u8) !Sema {
    14→    var tokenizer = Tokenizer.init(source);
    15→    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    16→    defer tokens.deinit();
    17→
    18→    while (true) {
    19→        const token = tokenizer.nextToken();
    20→        try tokens.append(token);
    21→        if (token.tag == .eof) break;
    22→    }
    23→
    24→    var parser = Parser.init(try tokens.toOwnedSlice(), source, allocator);
    25→    defer parser.deinit();
    26→
    27→    const ast = try parser.parseProgram();
    28→    defer ast.deinit();
    29→
    30→    var astgen = try AstGen.init(allocator, source);
    31→    defer astgen.deinit();
    32→    try astgen.genProgram(&ast);
    33→
    34→    const air = try allocator.create(Air);
    35→    air.* = Air.init(allocator);
    36→
    37→    return .{
    38→        .zir = astgen.zir,
    39→        .air = air,
    40→        .allocator = allocator,
    41→    };
    42→}
